package main

import (
	"bytes"
	"io"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/monaco/monaco/apps/backend/internal/errs"
	"github.com/monaco/monaco/apps/backend/internal/tools/flows"
)

func TestDocsEventsPrintsTheRegistryCatalog(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	if code := run(commands(), tools(nil), nil, []string{"docs", "events"}, &stdout, &stderr); code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	want := "# Event catalog\n\n" +
		"Generated by `monacoctl docs events` from the `internal/events` registry. Do not edit.\n\n" +
		"## `system.pinged`\n\n" +
		"Subject `events.system.pinged`, version 1.\n\n" +
		"| Field | Go type |\n| --- | --- |\n" +
		"| `v` | `int` |\n| `ping_id` | `uuid.UUID` |\n| `user_id` | `uuid.UUID` |\n| `note` | `string` |\n"
	if stdout.String() != want {
		t.Fatalf("stdout =\n%s\nwant\n%s", stdout.String(), want)
	}
}

func TestDocsRejectsAnUnknownTopic(t *testing.T) {
	t.Parallel()
	for _, args := range [][]string{{"docs"}, {"docs", "nope"}, {"docs", "events", "extra"}} {
		var stdout, stderr bytes.Buffer
		if code := run(commands(), tools(nil), nil, args, &stdout, &stderr); code != 2 || stdout.Len() != 0 ||
			stderr.String() != "usage: monacoctl docs errors|events|flows|logs\n" {
			t.Fatalf("%q: code=%d stdout=%q stderr=%q", args, code, stdout.String(), stderr.String())
		}
	}
}

func TestDocsFlowsRendersTheTSV(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name, tsv      string
		code           int
		stdout, stderr string
	}{
		{
			"valid", flows.Header + "\n" + pingRow + "\n", 0,
			"| # | Flow | Command / trigger | Events | Consumers |\n| --- | --- | --- | --- | --- |\n" +
				"| 01 | Ping | `Ping` on `poller:platform.retention` | `system.pinged` | none |\n", "",
		},
		{"malformed", flows.Header + "\n01\tPing\n", 1, "", "flows.tsv:2: has 2 columns, want 10\n"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			var stdout, stderr bytes.Buffer
			code := docsFlows(envWith(t, tc.tsv).Repo, &stdout, &stderr)
			if code != tc.code || stdout.String() != tc.stdout || stderr.String() != tc.stderr {
				t.Fatalf("code=%d stdout=%q stderr=%q", code, stdout.String(), stderr.String())
			}
		})
	}
}

func TestDocsFlowsFailsWhenTheTSVIsMissing(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	code := docsFlows(fstest.MapFS{}, &stdout, &stderr)
	if code != 1 || stdout.Len() != 0 || !strings.HasPrefix(stderr.String(), "monacoctl docs flows: ") {
		t.Fatalf("code=%d stdout=%q stderr=%q", code, stdout.String(), stderr.String())
	}
}

func TestDocsLogsPrintsTheMessageCatalogWithoutConfig(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	if code := run(commands(), tools(nil), nil, []string{"docs", "logs"}, &stdout, &stderr); code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	if !strings.HasPrefix(stdout.String(), "| Message | Required attrs |\n") ||
		!strings.Contains(stdout.String(), "| `boot.stopped` | `service`, `err` |\n") {
		t.Fatalf("stdout = %q, want the registry as a Markdown table", stdout.String())
	}
}

type failingWriter struct{}

func (failingWriter) Write([]byte) (int, error) { return 0, io.ErrClosedPipe }

func TestDocsLogsWriteFailureExits1(t *testing.T) {
	t.Parallel()
	var stderr bytes.Buffer
	code := docsLogs(failingWriter{}, &stderr)
	if code != 1 || !strings.HasPrefix(stderr.String(), "monacoctl docs logs: observability.WriteCatalog: internal") {
		t.Fatalf("docs logs = %d %q, want 1 and the wrapped error", code, stderr.String())
	}
}

func TestDocsErrorsPrintsTheCodeTable(t *testing.T) {
	t.Parallel()
	var stdout, stderr bytes.Buffer
	if code := run(commands(), tools(nil), nil, []string{"docs", "errors"}, &stdout, &stderr); code != 0 {
		t.Fatalf("exit code = %d, stderr = %q", code, stderr.String())
	}
	out := stdout.String()
	for _, want := range []string{
		"| Code | HTTP status | Retryable | Alerts | Message |\n| --- | --- | --- | --- | --- |\n",
		"| `db_unavailable` | 503 | yes | no | The service is temporarily unavailable. Try again shortly. |\n",
		"| `version_conflict` | 409 | no | no | This changed since you last loaded it. Refresh and try again. |\n",
		"| `panic` | 500 | no | yes | Something went wrong. |\n",
	} {
		if !strings.Contains(out, want) {
			t.Fatalf("stdout =\n%s\nwant a line %q", out, want)
		}
	}
	if rows := strings.Count(out, "\n| `"); rows != len(errs.All()) {
		t.Fatalf("got %d code rows, want %d", rows, len(errs.All()))
	}
}
